import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Phantom: Training Robots Without Robots Using Only Human Videos","description":"","frontmatter":{"title":"Phantom: Training Robots Without Robots Using Only Human Videos","arxiv":"2503.00779","date":"2025-03-02","authors":"Marion Lepert, Jiaying Fang, Jeannette Bohg","categories":"cs.RO","topics":"人类视频学习, 跨形态迁移, 模仿学习","outline":[2,2]},"headers":[],"relativePath":"papers/2503.00779.md","filePath":"papers/2503.00779.md","lastUpdated":null}'),l={name:"papers/2503.00779.md"};function e(i,s,m,c,r,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="phantom-training-robots-without-robots-using-only-human-videos" tabindex="-1">Phantom: Training Robots Without Robots Using Only Human Videos <a class="header-anchor" href="#phantom-training-robots-without-robots-using-only-human-videos" aria-label="Permalink to &quot;Phantom: Training Robots Without Robots Using Only Human Videos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.00779" target="_blank" rel="noreferrer">2503.00779</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-02</td></tr><tr><td><strong>作者</strong></td><td>Marion Lepert, Jiaying Fang, Jeannette Bohg</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用手部位姿估计给人类视频打上机器人动作标签，再把画面里的人手 inpaint 掉、贴上渲染的机器人，把人类视频直接变成可训练的机器人示教数据，全程零机器人数据。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 页给出的 HTML 版本是 <strong>v2</strong>（v1 2025-03-02，v2 2026-05-28），本文按 v2 全文撰写。论文已发表于 CoRL 2025。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人学习的瓶颈不是模型，是数据。Open X-Embodiment 这类努力已经把机器人数据推到百万级 episode，但与视觉/语言基座模型的语料仍差几个数量级，而且这些数据几乎全部来自遥操作——需要真机、需要人守着、需要把硬件搬到每一个新场景里去。作者关心的是一个渐近设定：人类视频会以极快速度增长，而机器人数据的增速被硬件成本锁死，当机器人数据占比趋近于零时，什么方法还能继续 scale。</p><p>人类视频有两个硬伤：没有动作标签，且人手与夹爪在像素上完全不像。本文要回答的问题是，能不能只靠人类视频、不碰任何机器人数据，训出一个可以零样本部署到真机的闭环视觉运动策略。若成立，采数据的门槛就从&quot;一台机械臂加一个遥操作员&quot;降到&quot;一台 RGBD 相机&quot;，数据多样性的成本结构被彻底改写。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>从人类视频学习有几条成熟路线，每条都在某个维度上被卡住。表征预训练（R3M 类）、奖励函数学习、世界模型这一支，把人类视频当作提升泛化的辅助信号，最终仍要真机数据来闭环。运动先验类工作如 MimicPlay 用人类视频训高层 planner，低层策略仍由遥操作数据训练；论文统计其数据里至少 75%（按采集时长算）是机器人数据。物体中心方法（ORION、DITTO）绕开形态差异，改成估计物体的 SE(3) 变换再让机器人复现，代价是遇到可形变物体、颗粒物、多物体就失效——因为&quot;物体的刚体位姿&quot;这个概念本身不成立。基于点流的方法（Track2Act、MotionTracks、Im2Flow2Act）用点轨迹替代刚体变换，缓解了物体类型限制，但仍需真机数据做残差精修：论文点名 MotionTracks 至少 22% 是遥操作数据，Track2Act 每个任务约 40 条真机示教，EgoMimic 平均 41% 来自遥操作。R+X 确实只用人类数据，但只做开环执行。</p><p>另一条线是机器人到机器人的数据编辑（Rovi-Aug、Shadow），思路是把源本体从图里抹掉、换成目标本体的渲染。这套方法很有效，但它依赖精确的本体感知与动作标签——这正是人类视频没有的东西，所以此前没人把它搬到人到机器人的设定。作者的判断是：这条路没被走通不是因为思路错，而是因为缺一个够好的手部位姿到动作的转换器。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2024 年前后有三件既成事实。第一，Rovi-Aug/Shadow 证明了&quot;把像素里的本体换掉&quot;足以消除视觉分布偏移，policy 不需要知道自己在什么机器上。第二，HaMeR 这类手部网格估计器已经能从单目图像给出 21 个关键点 + 778 个网格顶点，精度足以支撑毫米级以下的相对姿态。第三，几乎所有大规模机器人数据集都只用平行夹爪，动作空间就是末端位姿加一个开合度——这个动作空间恰好可以由拇指与食指两个指尖完全确定。</p><p>把三件事拼起来：如果人的捏取动作能被无歧义地映射成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathbf">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">R</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span>，那么&quot;人类视频缺动作标签&quot;这个问题就不存在了；如果 inpaint + 渲染覆盖能消除外观差异，那么&quot;人手不像夹爪&quot;这个问题也不存在了。剩下唯一的怀疑是精度：单目手部估计的绝对深度很差。而 RGBD 相机的深度图恰好可以用来做 ICP 配准，把 HaMeR 的相对形状锚定到绝对尺度上。到这一步，所有零件都是现成的，剩下的是敢不敢相信这套拼装出来的伪示教足够干净，能直接训 Diffusion Policy。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>策略看到的其实只有像素和动作两样东西。只要每一帧的像素里出现的是一只渲染出来的机器人手臂、且它的位姿正好等于标注的动作，这条数据对策略来说就与真机采集的数据无法区分——策略无从知道背后是人还是机器人。人到机器人的鸿沟因此不是一个需要&quot;学习&quot;去跨越的表征问题，而是一个可以在数据预处理阶段用分割、inpainting 与渲染直接&quot;抹平&quot;的编辑问题。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以论文里的 Sweep Trash 任务为例。人手持扫帚把六块垃圾扫进簸箕，第三人称 RGBD 相机记录全过程。</p><ul><li><strong>动作标注</strong>：每帧用 HaMeR 预测手部关键点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">X</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与网格 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">V</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；用 SAM2 分割出手，结合深度图得到部分点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；ICP 求刚体变换 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">V</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，并把同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 施加到关键点上。针对遮挡，把拇指与食指末两节关节约束成单自由度，避免 HaMeR 的球关节假设给出解剖学上不可能的手型。</li><li><strong>动作构造</strong>：位置取拇指尖与食指尖中点，姿态由拇指-食指关键点拟合的平面法向加拇指主轴确定，开合度取两指尖距离，并把单条轨迹里最小的 20% 距离强制置为完全闭合以抑制打滑。全部经已知外参转到机器人坐标系。</li><li><strong>视觉编辑</strong>：SAM2 分出人臂，E2FGVI 视频 inpainting 抹掉，用 MuJoCo 按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 渲染目标机器人并按深度做遮挡合成，叠回原图。</li><li><strong>训练与部署</strong>：在编辑后的数据上训 Diffusion Policy（DDIM，训练 100 步、推理 10 步）。推理时给真机观测再叠一层同样的虚拟机器人渲染，把训练与测试的像素分布对齐。Franka 用 OSC 控制，Kinova 用 IK。</li></ul><p>数据规模：Franka 五个任务各 268–313 条人类视频，Kinova 扫地任务 950 条，覆盖四种台面、约 80% 室内。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>方法本身的形式化很轻，核心只有两处。动作定义为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0585em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0585em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">6</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span><span class="mord">.</span></span></span></span></span></p><p>姿态用 6D 连续旋转表示而非四元数或欧拉角，是因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord">3</span><span class="mclose">)</span></span></span></span> 到任何三维或四维欧氏空间的映射都不连续，回归网络在不连续点附近误差爆炸；6D 表示（取旋转矩阵前两列再做 Gram-Schmidt）是连续的，这是回归旋转时的标准做法。</p><p>第二处是尺度锚定。HaMeR 输出的形状 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">V</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 内部一致但绝对位姿不可靠，ICP 求解</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3277em;vertical-align:-1.2777em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.309em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">T</span><span class="mrel mtight">∈</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span><span class="mopen mtight">(</span><span class="mord mtight">3</span><span class="mclose mtight">)</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.966em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord mathbf">T</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">v</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mord">Π</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">T</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">v</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose"><span class="mclose">∥</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Π</span></span></span></span> 取点云上的最近邻。关键点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">X</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与顶点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0995em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9495em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf" style="margin-right:0.016em;">V</span></span><span style="top:-3.2551em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由同一个 MANO 参数生成，二者共享同一个刚体自由度，所以把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 直接作用到关键点上是合法的——这一步是整条流水线里唯一让单目估计获得绝对尺度的地方，也是精度的咽喉。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>编辑策略哪种有效？</strong> 同分布场景五个任务、每个配置 25 次 rollout。Hand Inpaint（本文）0.92/0.72/0.64/0.72（放书/叠杯/打绳结/翻箱），扫地任务抓起扫帚 0.88、扫进 &gt;4 块 0.40。Hand Mask（Shadow 风格）成绩相当（0.92/0.52/0.60/0.76），但推理平均慢 73%，因为测试时要额外跑一个扩散模型生成手掩码。Red Line（EgoMimic 的编辑方式）与不做任何编辑的 Vanilla <strong>在全部任务上都是 0.0</strong>。这个 0 与 0.9 的断崖是全文最硬的证据：视觉本体对齐不是锦上添花，是有无之别。</p><p><strong>能否泛化到新场景？</strong> 950 条跨场景人类视频训练，在三个未见环境测试：户外草坪 0.72、室内休息区 0.84、室内休息区+未见台面 0.64。训练数据 80% 室内，室内成绩最好与此自洽；换台面掉 20 个点，作者归因于训练只覆盖四种台面。</p><p><strong>inpaint 质量重要吗？</strong> E2FGVI 0.84、OpenCV 低质量 inpaint 0.76、只做掩码不 inpaint 0.60。低质量 inpaint 只掉 8 个点，说明策略对 inpaint 伪影有相当强的耐受度；而 mask-only 的 0.60 远高于 Red Line 的 0.0，作者据此推断&quot;训练时叠上机器人渲染&quot;才是关键组件，去人臂只是次要的。</p><p><strong>与真机数据比精度损失多少？</strong> 同场景下 50 条：真机 0.52 vs 人类 0.44（Fisher 精确检验 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.778</span></span></span></span>）；100 条：0.88 vs 0.64（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.095</span></span></span></span>）；人类数据加到 300 条可到 0.84。也就是说单场景内人类数据确实更差，需要约 3 倍数据量才追平，作者的论点是这个代价换来了跨场景采集的可行性。附录另给出协同训练结果：100 条单场景真机数据在同分布 0.88、换场景直接归零，掺入 950 条多场景人类视频后升到 0.80。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：只要把人类视频里的手抹掉并换成按估计位姿渲染的机器人，视觉策略就无法区分人类示教与真机示教。动作标签由 HaMeR + 深度 ICP 从捏取手型直接读出，位置取两指尖中点、开合度取指尖距离。这样得到的数据足以训出闭环 Diffusion Policy 并零样本部署，六个任务上成功率最高 92%，且能泛化到户外草坪等未见场景。消融显示&quot;叠机器人渲染&quot;是必需项，&quot;高质量 inpaint&quot;只是加分项，只贴红线（EgoMimic 的做法）完全无效。代价是同场景下精度略逊真机数据，需约 3 倍样本量追平。</p><p><strong>3 句话版</strong>：人到机器人的鸿沟可以在数据预处理阶段用分割-inpaint-渲染直接消除，而不必在训练阶段去学。动作标签从手部网格估计加深度配准中免费获得。零机器人数据即可闭环部署，并保持跨场景泛化。</p><p><strong>1 句话版</strong>：把机器人画进人类视频里，人类视频就变成了机器人数据。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>人手能完成的动作，机器人沿同一条轨迹也能完成</strong>。整套方法把人的指尖中点直接当成夹爪目标位姿，完全没有对机器人的运动学可达性、关节限位、自碰撞与环境碰撞做任何投影或过滤。论文自己在 Limitations 里承认策略可能让机器人撞上环境，即使人手不会撞；也承认人指腹与夹爪指面的摩擦特性不同会导致物体运动不一致。这个假设一旦不成立，&quot;人类视频&quot;与&quot;机器人示教&quot;就不再是同一个分布，前面所有像素级对齐都白做——因为分布偏移搬到了动作空间。</p><p>论文为它提供的证据是间接的：六个任务都成功了，说明在这些准静态、桌面尺度、平行夹爪可解的任务上假设成立。缺的是反向证据——没有任何一个&quot;人能做而机器人做不了&quot;的任务被拿来测量退化曲线，也没有报告数据编辑阶段有多少帧因 IK 无解被丢弃。作者选的任务全部是本体形态相近时的最好情况。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要复现整套系统：只验证&quot;渲染叠加是否是必需组件&quot;这一条因果。取任一现成的真机遥操作数据集（如 DROID 的单任务子集），做四组处理后各训一个 Diffusion Policy：(a) 原图；(b) 把真机臂分割后 inpaint 掉、再按真值末端位姿渲染叠回同一台机器人；(c) 只 inpaint 不叠；(d) inpaint 后叠一条红线。测试时对应做同样编辑。度量同分布成功率。若 (a)≈(b) ≫ (c) &gt; (d)≈0，则复现了论文的核心排序，且证明该排序与&quot;数据是否来自人类&quot;无关，纯粹是像素占位符的问题——这会让 Phantom 的结论更强。若 (d) 并不为 0，则说明论文里 Red Line 的全线归零另有原因（例如遮罩把物体也涂黑了），需要重新解读。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是构造一个&quot;人手策略与机器人策略必须不同&quot;的任务。例如：把一个薄书从紧贴墙面的书架缝里抽出来。人可以侧着手腕、用指尖贴墙面滑入，夹爪的指宽与手腕的自由度使同样轨迹必然与墙碰撞。按 Phantom 的流水线，这类视频仍会被编辑成&quot;看起来正常&quot;的机器人数据——渲染器不做碰撞检测，深度遮挡只影响可见性不影响合法性——于是训练集里会出现大量物理上不可执行的目标位姿，策略会被稳定地训成一个会撞墙的策略。这类失败是可预测的，而且不会在论文选的六个任务上出现。</p><p>另一个方向是给现有结果提供替代解释。测试时论文在真机观测上<strong>再叠一层虚拟机器人渲染</strong>，也就是说部署时真实机械臂的像素被覆盖掉了。那么策略可能根本没有学会&quot;看机器人&quot;，而是学会了&quot;看那个渲染出来的、位姿由控制器已知的覆盖层&quot;——本质上等于把本体感知以图像形式喂了进去。检验方法：推理时把渲染覆盖层的位姿人为加一个固定偏移（真机实际位姿不变），若成功率随偏移量迅速崩塌，说明策略主要读的是覆盖层而非真实场景，&quot;视觉域对齐&quot;的叙事就要改写成&quot;图像化的本体感知注入&quot;。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：Phantom 把动作空间锁死在&quot;平行夹爪 + 捏取&quot;，这既是它能工作的原因，也是它的天花板——人类视频里绝大多数操作（推、压、勾、双手协同、用掌心承托）都无法被两个指尖表达。同时它完全不检查可执行性，把运动学交给运气。</p><p><strong>(b) 可借鉴的相邻工具</strong>：计算机图形学里的运动重定向（motion retargeting）已经处理了&quot;把源骨架动作映射到目标骨架且满足目标约束&quot;这一问题几十年，标准做法是把重定向写成带约束的时空优化，而不是逐帧的直接拷贝。</p><p><strong>(c) 新 framing 与第一个实验</strong>：把数据编辑从&quot;逐帧渲染&quot;升级为&quot;带约束的轨迹重定向&quot;——在生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">robot</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 时求解一条最接近人类指尖轨迹、同时满足机器人 IK 可达、无自碰撞、与深度图重建的场景无穿透的机器人轨迹，再按这条轨迹渲染。这样编辑出来的每一帧在物理上都是可执行的，且渲染与标签自动保持一致。第一个实验就用 § 11 的书架任务：对比&quot;直接拷贝&quot;与&quot;约束重定向&quot;两种编辑方式训出的策略，度量真机碰撞率与成功率。如果约束重定向能在直接拷贝彻底失败的任务上拿到非零成功率，那么 Phantom 的适用边界就从&quot;人机策略必须相同&quot;放宽到&quot;人机策略必须同伦&quot;，这是一个量级上的扩张，而不是加一个模块。</p>',47)])])}const u=a(l,[["render",e]]);export{o as __pageData,u as default};
